{
  "title": "Slow Windows Startup",
  "introduction": "Your Windows computer is experiencing slow startup performance. This is a common issue that can be resolved through several troubleshooting steps.",
  "steps": [
    {
      "step_number": 1,
      "title": "Check for Startup Programs",
      "description": "Open Task Manager (Ctrl+Shift+Esc), go to the Startup tab, and disable unnecessary programs that launch at startup. This can significantly improve boot speed."
    },
    {
      "step_number": 2,
      "title": "Run System File Checker",
      "description": "Open Command Prompt as Administrator and run: sfc /scannow. This will repair corrupted system files that might be causing slowdowns."
    },
    {
      "step_number": 3,
      "title": "Disable Unnecessary Services",
      "description": "Open Services (services.msc), find services marked as 'Automatic', and disable non-essential services that may be running in the background. Note: Only disable services you are certain are not critical for your system."
    },
    {
      "step_number": 4,
      "title": "Check Disk Performance",
      "description": "Open Command Prompt as Administrator and run: chkdsk /f. This will check and fix disk errors that could be slowing down your system."
    },
    {
      "step_number": 5,
      "title": "Update Drivers and Windows",
      "description": "Ensure your Windows OS and drivers are up to date. Go to Settings > Update & Security > Windows Update to check for updates. Also, update critical drivers through Device Manager."
    }
  ],
  "system": "Windows",
  "os": "Windows"
}

{
  "title": "Wi-Fi Connected but Websites Not Loading on Windows",
  "introduction": "This issue occurs when Windows shows Wi-Fi is connected but websites fail to load. Common causes include DNS problems, network configuration errors, or temporary network glitches.",
  "steps": [
    {
      "step_number": 1,
      "title": "Check Physical Network Connection",
      "description": "Ensure the Ethernet cable (if using wired) or Wi-Fi adapter is properly connected. Restart your router and modem to reset the network."
    },
    {
      "step_number": 2,
      "title": "Flush DNS Cache",
      "description": "Open Command Prompt as Administrator and run: ipconfig /flushdns. This clears DNS cache to resolve DNS-related issues."
    },
    {
      "step_number": 3,
      "title": "Test Internet Connectivity",
      "description": "Open Command Prompt and run: ping 8.8.8.8. If this fails, there's a network connectivity issue. If it works, proceed to next step."
    },
    {
      "step_number": 4,
      "title": "Reset TCP/IP Stack",
      "description": "In Command Prompt (Admin), run: netsh int ip reset. Then restart your computer. This resets TCP/IP settings to fix configuration errors."
    },
    {
      "step_number": 5,
      "title": "Check for Network Adapter Issues",
      "description": "Go to Device Manager > Network adapters. Right-click your Wi-Fi adapter and select 'Update driver'. If no updates are available, try uninstalling the driver and restarting to reinstall."
    },
    {
      "step_number": 6,
      "title": "Disable IPv6 (Temporary Fix)",
      "description": "Open Network and Sharing Center > Change adapter settings. Right-click your active connection > Properties > Uncheck 'Internet Protocol Version 6 (TCP/IPv6)' and click OK. Restart your computer."
    },
    {
      "step_number": 7,
      "title": "Run Network Troubleshooter",
      "description": "Go to Settings > Network & Internet > Status > Network troubleshooter. Follow the prompts to automatically fix common issues."
    }
  ],
  "system": "Windows",
  "os": "Windows"
}

