{
  "title": "Ubuntu Cannot Connect to Wireless Network",
  "introduction": "Ubuntu is unable to connect to wireless networks. This issue can be caused by various factors including driver problems, network configuration errors, or hardware issues.",
  "steps": [
    {
      "step_number": 1,
      "title": "Check Wireless Adapter Status",
      "description": "Open a terminal and run the command: `iwconfig` to check if your wireless adapter is detected and active. If the adapter is not listed, your wireless hardware may not be properly detected or enabled."
    },
    {
      "step_number": 2,
      "title": "Ensure Wireless is Enabled",
      "description": "If the wireless adapter is listed but not active, try enabling it through the system settings or by running: `sudo modprobe -r wl` followed by `sudo modprobe wl` (for wireless drivers like wl)."
    },
    {
      "step_number": 3,
      "title": "Check Network Manager Status",
      "description": "Ensure Network Manager is running: `systemctl status NetworkManager`. If it's inactive, start it with `sudo systemctl start NetworkManager`."
    },
    {
      "step_number": 4,
      "title": "Restart Network Manager",
      "description": "Restart Network Manager to refresh connections: `sudo systemctl restart NetworkManager`."
    },
    {
      "step_number": 5,
      "title": "Check for Wireless Driver Issues",
      "description": "Identify your wireless driver: `lspci | grep -i wireless`. If you're using a non-standard driver, install the correct driver using `sudo apt install firmware-iwlwifi` (for Intel wireless) or other relevant firmware packages."
    },
    {
      "step_number": 6,
      "title": "Check for Network Configuration Errors",
      "description": "Verify your wireless network configuration: `nmcli connection show`. If the connection is not active, try reconfiguring it with `nmcli connection modify [connection-name] wifi-ssid [your-ssid] wifi-password [your-password]`."
    },
    {
      "step_number": 7,
      "title": "Check for Wireless Network Scans",
      "description": "Scan for available networks: `nmcli device scan`. This will list available wireless networks. If your network isn't listed, it may be hidden or the network is not broadcasting."
    },
    {
      "step_number": 8,
      "title": "Check for Firewall or Security Software Interference",
      "description": "Temporarily disable firewall or security software to rule out interference: `sudo ufw disable` (for UFW firewall)."
    },
    {
      "step_number": 9,
      "title": "Reinstall Network Manager",
      "description": "If the issue persists, reinstall Network Manager: `sudo apt purge network-manager` followed by `sudo apt install network-manager`."
    },
    {
      "step_number": 10,
      "title": "Check for Hardware Issues",
      "description": "If all else fails, check if the wireless adapter is physically connected (e.g., USB dongle) and try a different adapter if possible."
    }
  ],
  "system": "Linux",
  "os": "Ubuntu"
}

