{
  "title": "Permission Denied Error in Linux",
  "introduction": "When you encounter a 'Permission denied' error while running a script in Linux, it typically means the current user does not have the necessary permissions to execute the script. This is a common issue that can be resolved by adjusting file permissions or changing the user's ownership.",
  "steps": [
    {
      "step_number": 1,
      "title": "Check the current permissions of the script",
      "description": "Use the `ls -l` command to view the permissions of the script. The output will show the file permissions, ownership, and other details. For example, if the output shows `-rwxr-xr-x 1 user group 1234 filename`, it means the user has execute permission but the group and others do not have execute permission."
    },
    {
      "step_number": 1,
      "title": "Change the script's ownership to the current user",
      "description": "Run `chown $USER:$USER script_name` to change the ownership of the script to the current user. This ensures the user has full control over the script."
    },
    {
      "step_number": 2,
      "title": "Adjust the script's permissions to allow execution",
      "description": "Use `chmod +x script_name` to add execute permission to the script. This command adds the execute bit to the file, allowing the user to run it."
    },
    {
      "step_number": 3,
      "title": "Verify the permissions after changes",
      "description": "Run `ls -l script_name` again to confirm the permissions have been updated. The output should show the execute permission for the user (e.g., `-rwxr-xr-x`)."
    },
    {
      "step_number": 4,
      "title": "Run the script with the correct permissions",
      "description": "Execute the script using `./script_name` or `bash script_name` (if the script is a shell script)."
    }
  ],
  "system": "Linux",
  "os": "Linux"
}

